<body>
<div class="card">
  <h2>Loan calculator</h2>
  <div class="sub">Amortized monthly payments at a fixed rate</div>

  <label>Loan amount: <span class="val" id="amtVal">275 000</span> kr</label>
  <input type="range" id="amount" min="50000" max="500000" step="1000" value="275000">

  <label>Loan term: <span class="val" id="yrsVal">5</span> years</label>
  <input type="range" id="years" min="1" max="15" step="1" value="5">

  <label>Interest rate: <span class="val" id="rateVal">5.0</span>%</label>
  <input type="range" id="rate" min="1" max="15" step="0.1" value="5">

  <div class="result">
    <div class="big" id="monthly">0 kr</div>
    <div class="biglabel">Monthly payment</div>
    <div class="row"><span>Total paid</span><span id="total">0 kr</span></div>
    <div class="row"><span>Total interest</span><span id="interest">0 kr</span></div>
    <div class="row"><span>Number of payments</span><span id="numpay">0</span></div>
  </div>
</div>
<script>
  const amt = document.getElementById('amount');
  const yrs = document.getElementById('years');
  const rate = document.getElementById('rate');
  const fmt = (n) => Math.round(n).toLocaleString('nb-NO') + ' kr';
  function calc() {
    const P = +amt.value;
    const n = +yrs.value * 12;
    const r = +rate.value / 100 / 12;
    const monthly = r === 0 ? P / n : P * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1);
    const total = monthly * n;
    const interest = total - P;
    document.getElementById('amtVal').textContent = (+amt.value).toLocaleString('nb-NO');
    document.getElementById('yrsVal').textContent = yrs.value;
    document.getElementById('rateVal').textContent = (+rate.value).toFixed(1);
    document.getElementById('monthly').textContent = fmt(monthly);
    document.getElementById('total').textContent = fmt(total);
    document.getElementById('interest').textContent = fmt(interest);
    document.getElementById('numpay').textContent = n;
  }
  amt.addEventListener('input', calc);
  yrs.addEventListener('input', calc);
  rate.addEventListener('input', calc);
  calc();
</script>
</body>
</html>
:::

The calculator uses the standard amortization formula (monthly payment = P·r·(1+r)ⁿ / ((1+r)ⁿ − 1)). Defaults: 275 000 kr over 5 years at 5%. Drag any slider to recalculate instantly. Note: this is an estimate and excludes fees, insurance and taxes.

